const items = ($json.value || []).filter(f => /\.(mp4|mkv|webm|mov|avi)$/i.test(f.name));
if (items.length === 0) throw new Error('Nenhum video encontrado na pasta');
return [{ json: items[0] }];

const t = $('Selecionar Vídeo').first().json;
const base = '/home/node/.n8n-files/';
return [{ json: { videoName: t.name, videoPath: base + t.name, audioPath: base + 'audio_full.wav' }}];

const c = $('Preparar Caminhos').first().json;
const out = $json.stdout || '';
const m = out.match(/DURATION:([\d.]+)/);
const duration = m ? parseFloat(m[1]) : 0;
const srtBase = '/home/node/.n8n-files/transcript_full';
return [{ json: { ...c, duration, srtBase, srtPath: srtBase + '.srt' } }];

const srt = $json.stdout || '';
const c = $('Preparar Whisper Blocos').first().json;
const BLOCK = 180;
const segs = srt.split(/\n\n+/).map(b => {
  const ls = b.trim().split('\n');
  const tl = ls.find(l => l.includes(' --> '));
  if (!tl) return null;
  const tm = tl.match(/(\d+):(\d+):(\d+),(\d+) --> (\d+):(\d+):(\d+),(\d+)/);
  if (!tm) return null;
  const s = +tm[1]*3600 + +tm[2]*60 + +tm[3] + +tm[4]/1000;
  const e = +tm[5]*3600 + +tm[6]*60 + +tm[7] + +tm[8]/1000;
  const txt = ls.filter(l => !l.match(/^\d+$/) && !l.includes(' --> ')).join(' ');
  return { s, e, txt };
}).filter(Boolean);
const blocks = []; let bs = 0, cur = [];
for (let i = 0; i < segs.length; i++) {
  const seg = segs[i]; cur.push(seg);
  if (seg.e - bs >= BLOCK || i === segs.length - 1) {
    blocks.push({ blockIndex: blocks.length+1, start: Math.round(bs), end: Math.round(seg.e), text: cur.map(x=>x.txt).join(' ') });
    bs = seg.e; cur = [];
  }
}
return [{ json: { ...c, srtContent: srt, blocks: JSON.stringify(blocks), blockCount: blocks.length } }];

const raw = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '').trim();
const match = raw.match(/\[[\s\S]*\]/);
if (!match) throw new Error('IA nao retornou JSON de blocos. Resposta: ' + raw.slice(0, 300));
let scores; try { scores = JSON.parse(match[0]); } catch(e) { throw new Error('JSON invalido: ' + e.message); }
if (!Array.isArray(scores)) scores = scores.blocks || scores.scores || [];
scores.sort((a,b) => b.score - a.score);
const qualified = scores.filter(s => s.score >= 70);
if (qualified.length === 0) throw new Error('Nenhum bloco atingiu nota minima de 70. Notas: ' + scores.map(s=>s.blockIndex+':'+s.score).join(', '));
const allBlocks = JSON.parse($('Dividir em Blocos').first().json.blocks || '[]');
const scoredBlocks = qualified.slice(0, 5).map(s => {
  const b = allBlocks.find(x => x.blockIndex === s.blockIndex) || {};
  return { blockIndex: s.blockIndex, score: s.score, reason: s.reason, start: b.start, end: b.end };
});
const topBlocksFull = allBlocks.filter(b => scoredBlocks.find(s => s.blockIndex === b.blockIndex));
const c = $('Preparar Whisper Blocos').first().json;
const summary = topBlocksFull.map(b => '=== Bloco ' + b.blockIndex + ' [' + b.start + 's-' + b.end + 's] (nota: ' + (scoredBlocks.find(s=>s.blockIndex===b.blockIndex)||{}).score + '/100) ===\n' + b.text).join('\n\n');
return [{ json: { ...c, srtContent: $('Dividir em Blocos').first().json.srtContent, topBlocksSummary: summary, scoredBlocks } }];

const raw = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch(_) { const m = raw.match(/\{[\s\S]*\}/) || raw.match(/\[[\s\S]*\]/); if (!m) throw new Error('IA nao retornou JSON de clipes. Resposta: ' + raw.slice(0, 300)); try { parsed = JSON.parse(m[0]); } catch(e) { throw new Error('JSON invalido: ' + e.message); } }
const clips = (() => { if (Array.isArray(parsed)) return parsed; const c = parsed.clips||parsed.clipes||parsed.cortes; if (c) return c; const a = Object.values(parsed).filter(v=>Array.isArray(v)&&v.length>0&&v[0]&&v[0].start!=null); return a[a.length-1]||[]; })().slice(0, 8);
const c = $('Preparar Whisper Blocos').first().json;
const vp = c.videoPath, vn = c.videoName;
const base = '/home/node/.n8n-files/';
const results = [];
for (let i = 0; i < clips.length; i++) {
  const clip = clips[i];
  const dur = clip.end - clip.start;
  if (dur < 45 - 10 || dur > 180) continue;
  if (results.length > 0 && clip.start < results[results.length-1].clipEnd - 5) continue;
  const idx = String(results.length+1).padStart(2,'0');
  const slug = (clip.title||'clip').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,40);
  const outPath   = base+'short_'+idx+'_'+slug+'.mp4';
  const audioPath = base+'clip_'+idx+'.wav';
  const srtBase   = base+'clip_'+idx;
  const srtPath   = srtBase+'.srt';
  const metaPath  = base+'clip_'+idx+'_meta.json';
  const ds = Math.round(dur);
  const scoredBlocks = $('Ranking dos Blocos').first().json.scoredBlocks || [];
  const blockScore = scoredBlocks.find(s => clip.start >= (s.start||0) && clip.start < (s.end||9999));
  const metaContent = JSON.stringify({ index:results.length+1, title:clip.title, slug, hook:clip.hook||'', reason:clip.reason||'', retention_score: clip.retention_score||null, block_score: blockScore ? blockScore.score : null, criteria: blockScore ? blockScore.criteria||null : null, start:clip.start, end:clip.end, duration:Math.floor(ds/60)+'m'+(ds%60)+'s', videoSource:vn }, null, 2);
  results.push({ clipStart:Math.max(0,clip.start), clipEnd:clip.end, idx, titleSlug:slug, hook:clip.hook||'', reason:clip.reason||'', videoPath:vp, videoName:vn, outPath, audioPath, metaPath, metaContent });
}
if (results.length === 0) {
  const info = clips.map((cl,i) => 'clip'+i+': start='+cl.start+' end='+cl.end+' dur='+(cl.end-cl.start).toFixed(1)).join('; ');
  throw new Error('Montar Clipes: 0 clipes aceitos. Parsed ' + clips.length + ' clipes da IA. ' + (info || 'IA retornou array vazio. Raw: ' + raw.slice(0, 500)));
}
return results;
